package com.mich.autoclipsync; import android.accessibilityservice.AccessibilityService; import android.view.accessibility.AccessibilityEvent; import android.content.*; public class ClipAccessibilityService extends AccessibilityService{ ClipboardManager cm; String last=""; volatile boolean running; public void onServiceConnected(){cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE); try{cm.addPrimaryClipChangedListener(()->observe("accessibility_listener"));}catch(Throwable t){} running=true; Thread th=new Thread(()->{while(running){observe("accessibility_poll"); try{Thread.sleep(250);}catch(Exception e){}}}); th.setDaemon(true); th.start(); observe("accessibility_connected");} public void onAccessibilityEvent(AccessibilityEvent e){observe("accessibility_event");} public void onInterrupt(){} public void onDestroy(){running=false; super.onDestroy();} void observe(String src){try{if(cm==null)cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE); if(cm!=null&&cm.hasPrimaryClip()&&cm.getPrimaryClip()!=null&&cm.getPrimaryClip().getItemCount()>0){CharSequence cs=cm.getPrimaryClip().getItemAt(0).coerceToText(this); String s=cs==null?"":cs.toString(); if(!s.equals(last)){last=s; ClipBridgeService.publishObservedText(s,src);}}}catch(Throwable t){}}}
